// 题目 AI 审阅后台接口封装。
//
// 路径与 ProblemEnrichmentController（web/controller/problem_enrichment.go）的方法名
// 按 AutoRegisterRoute 的驼峰转路径规则一一对应（与 permission.ts 同一约定）。
import httpRequest from "@/apis/axios-api";

import type { CodeResult } from "@/types/request";
import type {
  CuratorContext,
  EnrichCallItem,
  EnrichOverview,
  EnrichPage,
  EnrichProblemDetail,
  EnrichPublicDifficulty,
  EnrichReviewItem,
  EnrichStateStatus,
  EnrichStateItem,
  EnrichSummaryPayload,
  EnrichTagManageItem,
  EnrichWorkerConfig,
  SaveHumanAnnotationRequest,
} from "@/types/problem-enrichment";

// ── 状态监控 ──

export function GetEnrichStateList(
  status: EnrichStateStatus[] | null,
  page: number,
  pageSize: number
): Promise<CodeResult<EnrichPage<EnrichStateItem>>> {
  return httpRequest<unknown, CodeResult<EnrichPage<EnrichStateItem>>>({
    url: "/problem/enrichment/state/list",
    method: "get",
    params: {
      status: status && status.length > 0 ? status.join(",") : undefined,
      page,
      page_size: pageSize,
    },
  });
}

export function GetEnrichWorkerConfig(): Promise<CodeResult<EnrichWorkerConfig>> {
  return httpRequest<unknown, CodeResult<EnrichWorkerConfig>>({
    url: "/problem/enrichment/worker/config",
    method: "get",
  });
}

export function PostEnrichRequeue(problemId: number): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/requeue",
    method: "post",
    data: { problem_id: problemId },
  });
}

// 2026-10-11 移除：出题编辑页的「AI 生成标签」按钮已删，改为人工输入 + AI 标签只读展示；
// 审阅流水线的 tags 阶段不受影响（judge 侧按队列跑）。

export function PostEnrichBackfill(): Promise<CodeResult<{ inserted: number }>> {
  return httpRequest<unknown, CodeResult<{ inserted: number }>>({
    url: "/problem/enrichment/backfill",
    method: "post",
  });
}

// 运维总览仪表盘（状态分布/覆盖率/当日成本/worker 健康/阶段耗时）
export function GetEnrichOverview(): Promise<CodeResult<EnrichOverview>> {
  return httpRequest<unknown, CodeResult<EnrichOverview>>({
    url: "/problem/enrichment/overview",
    method: "get",
  });
}

// 调用账本分页（problemId/stage/status 均可选过滤）
export function GetEnrichCallList(
  params: { problem_id?: number; stage?: string; status?: string; page: number; page_size: number }
): Promise<CodeResult<EnrichPage<EnrichCallItem>>> {
  return httpRequest<unknown, CodeResult<EnrichPage<EnrichCallItem>>>({
    url: "/problem/enrichment/call/list",
    method: "get",
    params,
  });
}

// 手动重判单题（强制：处理中/成功/失败都重新入队，人工定稿类型保留）
export function PostEnrichRejudge(problemId: number): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/rejudge",
    method: "post",
    data: { problem_id: problemId },
  });
}

// 一键重判全部失败终态题目
export function PostEnrichRejudgeFailed(): Promise<CodeResult<{ reset: number }>> {
  return httpRequest<unknown, CodeResult<{ reset: number }>>({
    url: "/problem/enrichment/rejudge/failed",
    method: "post",
  });
}

// 切换「自动批量处理」开关：false（默认，手动试运行）只跑人工单独重判的题，true 全量自动
// 后端方法 PostAutoConsumeSet 经驼峰分词注册为 /auto/consume/set
export function PostEnrichAutoConsumeSet(
  enabled: boolean
): Promise<CodeResult<{ auto_consume: boolean }>> {
  return httpRequest<unknown, CodeResult<{ auto_consume: boolean }>>({
    url: "/problem/enrichment/auto/consume/set",
    method: "post",
    data: { enabled },
  });
}

// ── 标签管理 ──
//
// 2026-10-11 精简：只保留「一个概念一行」列表 + 通用名更新 + 置顶排序三个接口。
// 已随界面移除的入口：合并、别名增删、挂载题目、变更历史、疑似重复巡检、
// 展示名解锁（name_locked 机制整体删除）。

// 标签管理页分页：关键词同时匹配规范名与别名（后端 ListTagsForManage）
export function GetEnrichTagManageList(
  keyword: string,
  page: number,
  pageSize: number
): Promise<CodeResult<EnrichPage<EnrichTagManageItem>>> {
  return httpRequest<unknown, CodeResult<EnrichPage<EnrichTagManageItem>>>({
    url: "/problem/enrichment/tag/manage/list",
    method: "get",
    params: {
      keyword: keyword ? keyword : undefined,
      page,
      page_size: pageSize,
    },
  });
}

// 更新通用名：新名可以是组内已有的别名（从别名点选），也可以是全新叫法；
// 旧名直接废弃、不降为别名。重名返回 100126、名字非法（空/超长/归一化后为空）返回 100127。
export function PostEnrichTagRename(id: number, name: string): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/tag/rename",
    method: "post",
    data: { id, name },
  });
}

// 重建全表归一化名（匹配键）。迁移脚本刻意没有回填（SQL 复刻不了 Go 的归一化规则），
// 管理员点一次把历史数据补齐；幂等，返回实际更新的行数。
export function PostEnrichTagNormalizeBackfill(): Promise<CodeResult<{ updated: number }>> {
  return httpRequest<unknown, CodeResult<{ updated: number }>>({
    url: "/problem/enrichment/tag/normalize/backfill",
    method: "post",
  });
}

// 置顶 / 取消置顶标签，并设置它在置顶区内的顺序。
// 只影响标签云的展示顺序，不改变标签语义（后端因此不做额外校验）。
export function PostEnrichTagPin(
  id: number,
  pinned: boolean,
  order = 0
): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/tag/pin",
    method: "post",
    data: { id, pinned, order },
  });
}

// ── 标注审核 ──

export function GetEnrichReviewList(
  page: number,
  pageSize: number
): Promise<CodeResult<EnrichPage<EnrichReviewItem>>> {
  return httpRequest<unknown, CodeResult<EnrichPage<EnrichReviewItem>>>({
    url: "/problem/enrichment/review/list",
    method: "get",
    params: { page, page_size: pageSize },
  });
}

export function PostEnrichReviewSet(
  id: number,
  status: "approved" | "rejected",
  note?: string
): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/review/set",
    method: "post",
    data: { id, status, note },
  });
}

// 审核台上下文：题面（截断）+ 现有标签 + 五类最新标注
export function GetEnrichCuratorContext(
  problemId: number
): Promise<CodeResult<CuratorContext>> {
  return httpRequest<unknown, CodeResult<CuratorContext>>({
    url: "/problem/enrichment/curator/context",
    method: "get",
    params: { problem_id: problemId },
  });
}

// 保存人工校正版或纯人工标注，返回新标注行 id
export function PostEnrichAnnotationSave(
  req: SaveHumanAnnotationRequest
): Promise<CodeResult<{ id: number }>> {
  return httpRequest<unknown, CodeResult<{ id: number }>>({
    url: "/problem/enrichment/annotation/save",
    method: "post",
    data: req,
  });
}

// ── 公开产物（题详情页，无需管理权限） ──

export function GetProblemPublicSummary(
  problemId: number
): Promise<CodeResult<{ summary: EnrichSummaryPayload | null; difficulty: EnrichPublicDifficulty | null }>> {
  return httpRequest<unknown, CodeResult<{ summary: EnrichSummaryPayload | null; difficulty: EnrichPublicDifficulty | null }>>({
    url: "/problem/enrichment/public/summary",
    method: "get",
    params: { problem_id: problemId },
  });
}

// ── 单题产出详情（后台只读视图，含内部标注与版本历史） ──

export function GetEnrichDetail(
  problemId: number,
  problemKey?: string
): Promise<CodeResult<EnrichProblemDetail>> {
  return httpRequest<unknown, CodeResult<EnrichProblemDetail>>({
    url: "/problem/enrichment/detail",
    method: "get",
    // 详情页 path 路由用 key（可读 URL）；后端对 key 有数字兜底，老入口传 id 也兼容
    params: problemKey ? { problem_key: problemKey } : { problem_id: problemId },
  });
}
